/**
 * 产品展示卡（首页轮播 / 恢复邮件页画廊共用）
 * @param {string} base 图片 base 路径（不含扩展名）
 * @param {string} id 稳定标识，供 React key 与页面按语义筛选（勿随意改名）
 * @param {string} title 主标题
 * @param {string} caption 副标题
 */
const cartCard = (base, id, title, caption) => ({
  id,
  base,
  fallback: `${base}-960.jpg`,
  avif: [480, 960, 1600].map((w) => `${base}-${w}.avif ${w}w`).join(', '),
  title,
  caption,
});

