/**
 * 将用户输入规范化为 *.myshopify.com
 * @param {string} input
 * @returns {string}
 */
export function normalizeShopDomain(input) {
  if (!input || typeof input !== 'string') return '';
  let shop = input.trim().toLowerCase();
  shop = shop.replace(/^https?:\/\//, '').replace(/\/.*$/, '');
  if (!shop.includes('.')) {
    shop = `${shop}.myshopify.com`;
  }
  const match = shop.match(/^([a-z0-9][a-z0-9-]*)\.myshopify\.com$/);
  return match ? `${match[1]}.myshopify.com` : '';
}

/**
 * 构建 OAuth 安装 URL（Shopify 授权弹窗显示 Whaleal Cart）
 * @param {string} shopDomain
 * @returns {string}
 */
export function buildOAuthInstallUrl(shopDomain) {
  const shop = normalizeShopDomain(shopDomain);
  if (!shop) return '';
  return `${SHOPIFY_API_URL}/api/auth?shop=${encodeURIComponent(shop)}`;
}
