/**
 * PKCE（S256）与 JWT payload 解码工具 —— 自实现 OAuth2 授权码流程的一部分。
 *
 * 与 sms-console `src/auth/pkce.ts` 保持同一实现（生态内一处口径，便于两处对照维护）。
 *
 * @author 恒哥
 */

/** RFC 7636 code_verifier 允许的字符集（unreserved） */
const CHARS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~';

export function randomString(length) {
  const bytes = new Uint8Array(length);
  crypto.getRandomValues(bytes);
  let out = '';
  for (let i = 0; i < length; i++) out += CHARS[bytes[i] % CHARS.length];
  return out;
}

export function base64UrlEncode(buffer) {
  const bytes = new Uint8Array(buffer);
  let bin = '';
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

export async function pkcePair() {
  const verifier = randomString(64);
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(verifier));
  return { verifier, challenge: base64UrlEncode(digest) };
}

/** 解码 JWT payload（**不验签**，仅用于前端展示 email/roles；验签属服务端职责） */
export function decodeJwtPayload(jwt) {
  try {
    const part = jwt.split('.')[1];
    if (!part) return null;
    const bin = atob(part.replace(/-/g, '+').replace(/_/g, '/'));
    return JSON.parse(
      decodeURIComponent(
        bin.split('').map((c) => `%${`00${c.charCodeAt(0).toString(16)}`.slice(-2)}`).join(''),
      ),
    );
  } catch {
    return null;
  }
}
